@RunWith(MockitoJUnitRunner.class)
public class AbstractCommandLineRunner_createExterns_TriageGen2Test {

    @Spy
    private AbstractCommandLineRunner runner = new AbstractCommandLineRunner() {
        @Override
        protected Compiler createCompiler() {
            return null;
        }

        @Override
        protected CompilerOptions createOptions() {
            return null;
        }

        @Override
        protected CommandLineConfig getCommandLineConfig() {
            return config;
        }

        @Override
        protected DiagnosticGroups getDiagnosticGroups() {
            return null;
        }

        @Override
        protected void initOptionsFromFlags(CompilerOptions options) {
        }

        @Override
        protected void setRunOptions(CompilerOptions options) throws FlagUsageException, IOException {
        }

        @Override
        protected Compiler getCompiler() {
            return null;
        }

        @Override
        public void run() {
        }

        @Override
        protected PrintStream getErrorPrintStream() {
            return null;
        }

        @Override
        protected int doRun() throws FlagUsageException, IOException {
            return 0;
        }

        // Expose the protected method for testing
        public List<JSSourceFile> testCreateExterns() throws FlagUsageException, IOException {
            return createExterns();
        }

        // Mocking the internal call to createExternInputs via spy/override if necessary, 
        // but since we are testing the method that calls it, we need to control the behavior.
        // However, createExternInputs is likely a protected method in the same class.
        // We will use a spy on the runner to mock createExternInputs.
        @Override
        protected List<JSSourceFile> createExternInputs(List<String> externs) throws IOException {
            return createExternInputsStub;
        }

        protected List<JSSourceFile> createExternInputsStub;
    };

    private CommandLineConfig config;

    @Before
    public void setUp() {
        config = mock(CommandLineConfig.class);
        // We use reflection or a subclass to inject the config into the runner if it's a field
        // Since the code says 'config.externs', we assume config is a field in AbstractCommandLineRunner
        try {
            java.lang.reflect.Field configField = AbstractCommandLineRunner.class.getDeclaredField("config");
            configField.setAccessible(true);
            configField.set(runner, config);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testCreateExterns_Success() throws FlagUsageException, IOException {
        List<String> externPaths = ImmutableList.of("extern1.js", "extern2.js");
        when(config.externs).thenReturn(externPaths);

        List<JSSourceFile> expectedFiles = ImmutableList.of(
            mock(JSSourceFile.class),
            mock(JSSourceFile.class)
        );

        // Inject the behavior via the spy's stub field
        ((AbstractCommandLineRunner) runner).createExternInputsStub = expectedFiles;

        List<JSSourceFile> result = runner.testCreateExterns();

        assertThat(result).isEqualTo(expectedFiles);
    }

    @Test
    public void testCreateExterns_EmptyExterns() throws FlagUsageException, IOException {
        when(config.externs).thenReturn(ImmutableList.of());

        List<JSSourceFile> expectedFiles = ImmutableList.of();
        ((AbstractCommandLineRunner) runner).createExternInputsStub = expectedFiles;

        List<JSSourceFile> result = runner.testCreateExterns();

        assertThat(result).isEmpty();
    }

    @Test(expected = FlagUsageException.class)
    public void testCreateExterns_ThrowsFlagUsageException() throws FlagUsageException, IOException {
        when(config.externs).thenReturn(ImmutableList.of("invalid"));

        // We need to simulate the exception being thrown from the underlying method
        doThrow(new FlagUsageException("Usage error", null))
            .when(runner).createExternInputs(ImmutableList.of("invalid"));

        // Since we can't easily doThrow on a method that isn't a mock, 
        // we rely on the fact that our spy allows overriding.
        // Let's redefine the behavior for this specific test case.
        new AbstractCommandLineRunner() {
            @Override protected Compiler createCompiler() { return null; }
            @Override protected CompilerOptions createOptions() { return null; }
            @Override protected CommandLineConfig getCommandLineConfig() { return config; }
            @Override protected DiagnosticGroups getDiagnosticGroups() { return null; }
            @Override protected void initOptionsFromFlags(CompilerOptions options) {}
            @Override protected void setRunOptions(CompilerOptions options) {}
            @Override protected Compiler getCompiler() { return null; }
            @Override public void run() {}
            @Override protected PrintStream getErrorPrintStream() { return null; }
            @Override protected int doRun() { return 0; }
            @Override protected List<JSSourceFile> createExternInputs(List<String> externs) throws IOException {
                throw new FlagUsageException("Usage error", null);
            }
            public List<JSSourceFile> testCreateExterns() throws FlagUsageException, IOException {
                return createExterns();
            }
        }.testCreateExterns();
    }

    @Test(expected = IOException.class)
    public void testCreateExterns_ThrowsIOException() throws FlagUsageException, IOException {
        when(config.externs).thenReturn(ImmutableList.of("file.js"));

        // Create a specialized spy to throw IOException
        AbstractCommandLineRunner errorRunner = new AbstractCommandLineRunner() {
            @Override protected Compiler createCompiler() { return null; }
            @Override protected CompilerOptions createOptions() { return null; }
            @Override protected CommandLineConfig getCommandLineConfig() { return config; }
            @Override protected DiagnosticGroups getDiagnosticGroups() { return null; }
            @Override protected void initOptionsFromFlags(CompilerOptions options) {}
            @Override protected void setRunOptions(CompilerOptions options) {}
            @Override protected Compiler getCompiler() { return null; }
            @Override public void run() {}
            @Override protected PrintStream getErrorPrintStream() { return null; }
            @Override protected int doRun() { return 0; }
            @Override protected List<JSSourceFile> createExternInputs(List<String> externs) throws IOException {
                throw new IOException("IO error");
            }
            public List<JSSourceFile> testCreateExterns() throws FlagUsageException, IOException {
                return createExterns();
            }
        };

        errorRunner.testCreateExterns();
    }
}
